function kkPlayer(html){var m=html.match(/\bconst\s+playSource\s*=\s*\{\s*src\s*:\s*("(?:[^"\\]|\\.)*")\s*,\s*type\s*:\s*("(?:[^"\\]|\\.)*")\s*,?\s*\}\s*;/);if(!m)throw new Error('可可播放器结构已变化，不使用演示地址');var url=JSON.parse(m[1]),type=JSON.parse(m[2]);if(!url)throw new Error('此线路原站未提供网页直连，可能需要原站APP或解析器');url=pmUrl(url);if(type==='application/x-mpegURL'&&/\.m3u8(?:[?#]|$)/i.test(url)||type==='video/mp4'&&/\.mp4(?:[?#]|$)/i.test(url))return {url:url,type:type};throw new Error('可可播放器未提供匹配的M3U8/MP4直连');}
